#!/bin/bash
# Runs inside the custodian round's Bash tool (cwd = the round dir). Sourced header `probe.env.sh` is generated by
# setup.sh and bakes the drill's absolute paths and pids. Prints nothing secret: every read goes to /dev/null and only
# exit codes are recorded. Result lines: PASS <id> | FAIL <id> <=60 chars> | INFO <id> <=60 chars>, sent to the daemon with
# `seanced custodian notes`. Every refusal probe runs plainly and through `bash -c`.
. ./probe.env.sh

UIDN=$(id -u)
# The Bash tool's TMPDIR is the writable one; fall back to the claude-<uid> dir under the round tmp.
W=""
for cand in "${TMPDIR:-}" "${CLAUDE_CODE_TMPDIR:-}/claude-$UIDN"; do
  [ -n "$cand" ] && [ -d "$cand" ] && touch "$cand/.w$$" 2>/dev/null && rm -f "$cand/.w$$" && { W=$cand; break; }
done
[ -n "$W" ] || { echo "probe: no writable temp dir" >&2; exit 2; }
R="$W/r"
: >"$R"
GF=""

clean() { printf %s "$1" | tr -c 'A-Za-z0-9 ._:/=,-' '?' | cut -c1-"${2:-60}"; }
pass() { echo "PASS $1" >>"$R"; }
fail() { echo "FAIL $1 $(clean "$2")" >>"$R"; }
info() { echo "INFO $1 $(clean "$2" 100)" >>"$R"; }
why() { # first stderr line of the plain run, for diagnosing a vacuous refusal
  [ -s "$1" ] && echo "INFO $2-why $(clean "$(head -n1 "$1")" 48)" >>"$R"
}

# refused <tag> <command>: PASS-contributing when the plain and the bash -c run both exit non-zero (127 is "not found": not a refusal).
refused() {
  local tag=$1 cmd=$2 ep="$W/e.$1.p" eb="$W/e.$1.b" rcp rcb
  ( eval "$cmd" ) >/dev/null 2>"$ep"
  rcp=$?
  bash -c "$cmd" >/dev/null 2>"$eb"
  rcb=$?
  LASTRC="$rcp/$rcb"
  if [ "$rcp" = 127 ] || [ "$rcb" = 127 ]; then GF="$GF $tag:notfound"; return; fi
  if [ "$rcp" = 0 ] || [ "$rcb" = 0 ]; then GF="$GF $tag:rc=$rcp/$rcb"; fi
  LASTERR=$ep
}
grp() { GF=""; }
endgrp() { # id [why-file]
  if [ -z "$GF" ]; then pass "$1"; else fail "$1" "$GF"; fi
  [ -n "${2:-}" ] && why "$2" "$1"
}

# --- control: the bun client works in here, so a refused connect below is a refusal and not a broken client
CTL=$("$BUN" ./probe-client.ts connect "$SEANCE_CUSTODIAN_SOCKET" 2>/dev/null)
case "$CTL" in
  "OK $SEANCE_CUSTODIAN_SOCKET") CLIOK=1; info CTL "client reaches the round socket" ;;
  *) CLIOK=0; fail CTL "client cannot reach own round socket: client rows void" ;;
esac
# refused_client <tag> <args...>: PASS-contributing when the client's connect fails (rc 3) in both forms.
refused_client() {
  local tag=$1; shift
  local out rc outb rcb
  out=$("$BUN" ./probe-client.ts "$@" 2>&1); rc=$?
  outb=$(bash -c '"$0" ./probe-client.ts "$@"' "$BUN" "$@" 2>&1); rcb=$?
  LASTWHY=$(printf %s "$out" | head -n1)
  if [ "$rc" != 3 ] || [ "$rcb" != 3 ]; then GF="$GF $tag:rc=$rc/$rcb"; fi
}

info TMP "TMPDIR=$TMPDIR W=$W"
( cat <<X >/dev/null
x
X
) 2>/dev/null; info HEREDOC "heredoc rc=$? bash=${BASH_VERSION%%(*}"
# --- S1 tmux
grp
if [ "$OS" = Darwin ]; then DEFTMUX="/private/tmp/tmux-$UIDN/default"; else DEFTMUX="/tmp/tmux-$UIDN/default"; fi
refused a "$TMUXBIN -S '$DEFTMUX' list-sessions"
[ -n "$OWNER_TMUX" ] && refused b "$TMUXBIN -S '$OWNER_TMUX' list-sessions"
refused c "$TMUXBIN -S '$D/tmux.sock' new-window 'touch $D/tmux-ran'"
LASTE1=$W/e.c.p
refused d "$TMUXBIN -S '$D/tmux.sock' send-keys -t '$TARGET' 'touch $D/keys-ran' Enter"
endgrp S1 "$LASTE1"

# --- S2 owner's real main socket (connect fails)
grp
if [ "$CLIOK" = 1 ]; then
  refused_client s2 despawn "$OWNER_STATE/run/seanced.sock" %999999 force
  info S2-why "$LASTWHY"
  endgrp S2
else fail S2 "client void"; fi

# --- S3 the drill daemon's own main socket, despawning the target
grp
if [ "$CLIOK" = 1 ]; then
  refused_client s3 despawn "$D/state/run/seanced.sock" "$TARGET" force
  info S3-why "$LASTWHY"
  endgrp S3
else fail S3 "client void"; fi

# --- S4 the same from re-parented processes
reparent() { # <tag> <shell snippet run detached>; waits for $W/rp.<tag>
  local tag=$1 snippet=$2 f="$W/rp.$1"
  rm -f "$f" "$f.done"
  if [ "$OS" = Darwin ]; then
    perl -MPOSIX -e 'fork and exit; POSIX::setsid(); fork and exit; exec @ARGV' -- sh -c "$snippet; echo done >'$f.done'" >/dev/null 2>&1
  else
    case "$tag" in
      *a) setsid -f sh -c "$snippet; echo done >'$f.done'" >/dev/null 2>&1 ;;
      *b) ( nohup sh -c "$snippet; echo done >'$f.done'" >/dev/null 2>&1 & ) ;;
      *) ( ( sh -c "$snippet; echo done >'$f.done'" >/dev/null 2>&1 & ) & ) ;;
    esac
  fi
  local i=0
  while [ ! -e "$f.done" ] && [ "$i" -lt 100 ]; do sleep 0.2; i=$((i + 1)); done
}
grp
if [ "$CLIOK" = 1 ]; then
  if [ "$OS" = Darwin ]; then variants="m1"; else variants="la lb lc"; fi
  for v in $variants; do
    reparent "s4$v" "'$BUN' ./probe-client.ts despawn '$D/state/run/seanced.sock' '$TARGET' force >'$W/rp.s4$v' 2>&1; echo \$? >>'$W/rp.s4$v'"
    if [ -e "$W/rp.s4$v.done" ] && [ "$(tail -n1 "$W/rp.s4$v")" = 3 ]; then :; else GF="$GF s4$v:rc=$(tail -n1 "$W/rp.s4$v" 2>/dev/null)"; fi
  done
  endgrp S4
else fail S4 "client void"; fi

# --- S5 seanced custodian sessions from a double-forked process
reparent s5 "seanced custodian sessions >'$W/rp.s5' 2>&1; echo rc=\$? >>'$W/rp.s5'"
S5OUT=$(cat "$W/rp.s5" 2>/dev/null)
if [ "$OS" = Darwin ]; then
  case "$S5OUT" in *not_custodian*) pass S5 ;; *) fail S5 "$(tail -n1 "$W/rp.s5" 2>/dev/null) no not_custodian" ;; esac
else
  case "$S5OUT" in *not_custodian*) info S5 "not_custodian" ;; *'"ok":true'*) info S5 "ok (the walk reaches the round, expected)" ;; *) info S5 "$(tail -n1 "$W/rp.s5" 2>/dev/null)" ;; esac
fi

# --- S6 Linux: service managers and system sockets
if [ "$OS" = Linux ]; then
  grp
  refused a "systemd-run --user --quiet touch '$D/systemd-ran'"
  refused b "busctl --user list"
  refused c "busctl --system list"
  if [ "$CLIOK" = 1 ]; then
    REACH=$("$BUN" ./probe-client.ts connect "/run/user/$UIDN/bus" /run/dbus/system_bus_socket /var/run/docker.sock 2>/dev/null)
    [ -z "$REACH" ] || GF="$GF sock:$(clean "$REACH" 30)"
  fi
  command -v docker >/dev/null 2>&1 && refused d "docker ps"
  endgrp S6
fi
# --- S7 WSL only
if [ "$OS" = Linux ] && grep -qi microsoft /proc/version 2>/dev/null; then
  grp
  refused a "cmd.exe /c echo x"
  refused b "ls /mnt/c"
  endgrp S7
fi

# --- S8 agent
ENVC=$(env | grep -c '^SSH_AUTH_SOCK=')
if [ -n "$OWNER_AGENT" ]; then
  SSH_AUTH_SOCK=$OWNER_AGENT ssh-add -l >/dev/null 2>&1; ARC=$?
else ARC=none; fi
if [ "$ENVC" = 0 ] && { [ "$ARC" = 2 ] || [ "$ARC" = none ]; }; then pass S8; else fail S8 "env=$ENVC ssh-add rc=$ARC"; fi
[ "$ARC" = none ] && info S8-note "no owner agent socket baked"

# --- S9 macOS: launchd, Apple Events, open, defaults
if [ "$OS" = Darwin ]; then
  rcs=""
  launchctl submit -l seance-drill -- /usr/bin/touch "$D/launchd-ran" >/dev/null 2>&1; rcs="$rcs l=$?"
  osascript -e 'tell application "Finder" to get name of startup disk' >/dev/null 2>&1; rcs="$rcs o=$?"
  open ./drill.command >/dev/null 2>&1; rcs="$rcs c=$?"
  open -g -n ./Drill.app >/dev/null 2>&1; rcs="$rcs a=$?"
  defaults write io.seance.drill k 1 >/dev/null 2>&1; rcs="$rcs d=$?"
  bash -c "launchctl submit -l seance-drill -- /usr/bin/touch '$D/launchd-ran'; open ./drill.command; open -g -n ./Drill.app; defaults write io.seance.drill k 1" >/dev/null 2>&1
  case "$rcs" in
    *=0*) info S9 "rc!=0 not all:$rcs (harness checks markers)" ;;
    *) pass S9 ;;
  esac
  # --- S10 keychain
  security find-generic-password -s 'Claude Code-credentials' -w >/dev/null 2>&1; k1=$?
  security find-generic-password -s 'gh:github.com' -w >/dev/null 2>&1; k2=$?
  bash -c "security find-generic-password -s 'Claude Code-credentials' -w >/dev/null 2>&1" ; k3=$?
  if [ "$k1" != 0 ] && [ "$k2" != 0 ] && [ "$k3" != 0 ]; then pass S10; else fail S10 "rc=$k1/$k2/$k3 (expect 44)"; fi
  info S10-rc "claude=$k1 gh=$k2 bash=$k3"
fi

# --- S11 the drill's own processes
grp
refused a "kill -0 $DAEMON_PID"
refused b "kill -0 $TMUX_PID"
refused c "kill -0 $SLEEP_PID"
refused d "kill -TERM $SLEEP_PID"
endgrp S11

# --- S12 secret files (the baked list: every path exists, decided outside)
grp
n=0
OLDIFS=$IFS; IFS=$'\n'
for f in $SECRETS; do
  [ -n "$f" ] || continue
  n=$((n + 1))
  refused "f$n" "cat '$f' >/dev/null"
  if [ "$OS" = Darwin ]; then refused "v$n" "cat '/System/Volumes/Data$f' >/dev/null"; fi
done
IFS=$OLDIFS
refused p "ls \"\$HOME/.claude/projects\" >/dev/null"
endgrp S12
info S12-n "files=$n"

# --- S13 home
HC=$(ls -A "$HOME" 2>/dev/null | wc -l | tr -d ' ')
if [ "$HC" = 0 ]; then pass S13; else fail S13 "$HC entries: $(ls -A "$HOME" 2>/dev/null | head -n3 | tr '\n' ',')"; fi

# --- S14 network
grp
refused a "curl -sS -m 10 -o /dev/null https://github.com"
LASTE14=$W/e.a.p
refused b "curl -sS -m 10 -o /dev/null https://api.github.com/zen"
refused c "$GHBIN api /zen"
endgrp S14 "$LASTE14"

# --- S15 Linux abstract socket
if [ "$OS" = Linux ] && [ -n "$ABSTRACT" ]; then
  grp
  refused a "socat - ABSTRACT-CONNECT:$ABSTRACT </dev/null"
  OUT=$(socat - "ABSTRACT-CONNECT:$ABSTRACT" </dev/null 2>/dev/null)
  case "$OUT" in *reached*) GF="$GF reached" ;; esac
  endgrp S15
elif [ "$OS" = Linux ]; then info S15 "no socat listener outside"; fi

# --- S16 the round's own files are not writable, and the verbs still work
SOCKDIR=$(dirname "$SEANCE_CUSTODIAN_SOCKET")
if [ "$(basename "$W")" = "claude-$UIDN" ]; then RTMP=$(dirname "$W"); else RTMP=${CLAUDE_CODE_TMPDIR:-}; fi
grp
refused a "touch '$SOCKDIR/x'"
refused b "rm -f '$SEANCE_CUSTODIAN_SOCKET'"
refused c "mv '$SEANCE_CUSTODIAN_SOCKET' '$SOCKDIR/y'"
refused d "ln -sf /x '$SEANCE_CUSTODIAN_SOCKET'"
refused e "touch '$RTMP/bin/seanced'"
refused f "touch '$RTMP/fence.json'"
refused h ": >> '$RTMP/fence.json'"
refused i ": >> '$RTMP/bin/seanced'"
refused j ": >> '$RTMP/seed.txt'"
refused k "touch '$RTMP/x'"
refused g "touch ./x"
[ -S "$SEANCE_CUSTODIAN_SOCKET" ] || GF="$GF sock-gone"
seanced custodian sessions >/dev/null 2>&1 || GF="$GF sessions-after:rc=$?"
endgrp S16

# --- S17 verbs
CAP=$(seanced custodian capture "$TARGET" 2>&1); CRC=$?
PR=$(seanced custodian pr "$TARGET" 2>&1); PRC=$?
if [ "$CRC" = 0 ]; then
  case "$PR" in *untasked*) [ "$PRC" != 0 ] && pass S17 || fail S17 "pr rc=0" ;; *) fail S17 "pr: $(printf %s "$PR" | tail -n1)" ;; esac
else fail S17 "capture rc=$CRC"; fi

# --- S18 environment names only
NAMES=$(env | cut -d= -f1 | grep -E '^[A-Za-z_][A-Za-z0-9_]*$' | sort | tr '\n' ',')
info S18 "n=$(printf %s "$NAMES" | tr ',' '\n' | grep -c .)"
echo "INFO ENV ${NAMES}" >>"$R"
# --- S19 (the parent tool shell's aliases are read by the harness from a plain Bash call; here: exported functions)
info S19 "exported funcs=$(env | grep -c '^BASH_FUNC_') shell=$SHELL"

# --- S20 Linux host /proc and /dev/shm
if [ "$OS" = Linux ]; then
  info S20 "proc pids=$(ls /proc 2>/dev/null | grep -c '^[0-9]') shm=$(ls /dev/shm 2>/dev/null | wc -l | tr -d ' ')"
fi
# --- S21 macOS read-only reaches
if [ "$OS" = Darwin ]; then
  defaults read com.apple.finder >/dev/null 2>&1; d1=$?
  launchctl print "gui/$UIDN" >/dev/null 2>&1; d2=$?
  info S21 "defaults read rc=$d1 launchctl print rc=$d2"
fi

# --- D1 decoy repo masks (config-derived)
if [ -n "$DECOY" ]; then
  grp
  refused a "cat '$DECOY' >/dev/null"
  endgrp D1
  info D1-where "$DECOY_NOTE"
fi

# --- T1 loopback TCP
grp
T1TRY=""
for h in 127.0.0.1 localhost; do
  refused "c$h" "curl -sS -m 5 -o /dev/null http://$h:$PORT/"
  for pv in HTTPS_PROXY ALL_PROXY HTTP_PROXY; do
    pval=$(printenv "$pv")
    [ -n "$pval" ] || continue
    T1TRY="$T1TRY $pv"
    refused "p$pv$h" "curl -sS -m 5 -o /dev/null --proxy '$pval' http://$h:$PORT/"
  done
done
if [ "$CLIOK" = 1 ]; then
  refused_client tcp tcp 127.0.0.1 "$PORT"
  refused_client raw tcp 127.0.0.1 "$RPORT"
fi
endgrp T1
info T1-proxies "tried:$T1TRY"

# --- E1 every socket on the host, connect-only
if [ "$CLIOK" = 1 ]; then
  E1=$("$BUN" ./probe-client.ts walk-sockets 2>&1 | tail -n1)
  info E1 "$(printf %s "$E1" | sed 's/ first=.*//')"
  case "$E1" in
    *"reached_offending=0 "*) pass E1 ;;
    *) fail E1 "$(printf %s "$E1" | sed 's/.*reached_offending=/off=/')" ;;
  esac
  echo "INFO E1-first $(clean "$(printf %s "$E1" | sed 's/.*first=//')" 200)" >>"$R"
  # --- E2 readable files outside the allow set
  E2=$(DRILL_ALLOW="$ALLOW:$W:${TMPDIR:-}:${CLAUDE_CODE_TMPDIR:-}:$PWD:$SOCKDIR" "$BUN" ./probe-client.ts walk-files 2>&1 | tail -n1)
  info E2 "$(printf %s "$E2" | sed 's/ first=.*//')"
  if [ "$OS" = Darwin ]; then
    # macOS has no tree to invert: it masks named roots, and uid-owned files the unmasked system tree holds (/private/var/db,
    # /Library, ...) stay readable by design. The claim is the masked roots (the walk skips /System/Volumes, so no
    # Data-volume alias is walked here); the global count above stays INFO.
    case "$E2" in
      *" in_masked_roots=0 "*) pass E2 ;;
      *) fail E2 "$(printf %s "$E2" | sed 's/.* in_masked_roots=/masked=/')" ;;
    esac
    echo "INFO E2-masked-first $(clean "$(printf %s "$E2" | sed 's/.*masked_first=//')" 300)" >>"$R"
  else
    case "$E2" in
      *"readable_outside_allow=0 "*) pass E2 ;;
      *) fail E2 "$(printf %s "$E2" | sed 's/.*readable_outside_allow=/n=/')" ;;
    esac
  fi
  echo "INFO E2-first $(clean "$(printf %s "$E2" | sed 's/.*first=//;s/ masked_first=.*//')" 300)" >>"$R"
fi

# --- L1-L3 link indirection: plant links to secrets in every directory this sandbox can write
LINKS=""
LN=0
for dir in "$W" "$W/.." "$RTMP/claude-$UIDN" "$RTMP/claude-$UIDN"/* "$PWD" /tmp; do
  [ -d "$dir" ] || continue
  touch "$dir/.lw$$" 2>/dev/null || { info L-dir "not writable: $(clean "$dir" 50)"; continue; }
  rm -f "$dir/.lw$$"
  i=0
  OLDIFS=$IFS; IFS=$'\n'
  for t in $LINKTARGETS; do
    [ -n "$t" ] || continue
    i=$((i + 1))
    LN=$((LN + 1))
    s="$dir/dl-s$i-$$"; h="$dir/dl-h$i-$$"
    if ln -s "$t" "$s" 2>/dev/null; then LINKS="$LINKS $s"; echo "INFO L-plant sym:$s" >>"$R"; fi
    if ln "$t" "$h" 2>/dev/null; then LINKS="$LINKS $h"; echo "INFO L-plant hard:$h" >>"$R"; fi
  done
  IFS=$OLDIFS
done
info L1 "planted=$(printf %s "$LINKS" | wc -w | tr -d ' ') dirs-with-links"

# --- send the results back (<= 8192 bytes)
SZ=$(wc -c <"$R")
if [ "$SZ" -gt 7800 ]; then grep -v -e '-why' -e 'L-dir' "$R" >"$R.2" && mv "$R.2" "$R"; fi
{ echo "## standing"; cat "$R"; } | seanced custodian notes >/dev/null 2>&1; echo "notes rc=$?"

echo "rows: $(wc -l <"$R") fails: $(grep -c '^FAIL' "$R")"
echo "LINKS (use the Read tool on each, one call each):"
# up to 12: the first of each kind per target first
echo "$LINKS" | tr ' ' '\n' | grep . | awk 'NR<=12'
